const ctx = $('Build Draft Context').first().json;
const raw = String($input.first().json.text || '').replace(/```json|```/g, '').trim();
let d = {};
try { d = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { d = {}; }
const list = a => Array.isArray(a) ? a.filter(Boolean).map(String) : [];
const bullets = a => list(a).map(x => '- ' + x).join('\n') || '- none';
const core = String(d.draft_text || '').trim();
const namePat = /[\[<{(]\s*(?:(?:your|applicant|candidate|full)\s+)*name\s*[\]>})]|\b(?:your|applicant|candidate|full)\s+(?:full\s+)?name\b/gi;
const fillName = t => ctx.fullName ? String(t).replace(namePat, ctx.fullName) : String(t);
const subject = fillName(String(ctx.subjectRequired || d.email_subject || ('Application: ' + ctx.title)).trim());
const body = core ? fillName(core) + '\n\n' + ctx.signature : '';
const leftover = (body + ' ' + subject).match(/\[[^\]\n]{2,40}\]/g) || [];
let tg = 'Draft for ' + ctx.title + ' at ' + ctx.company + '\n' +
  'Send to: ' + (ctx.toEmail || 'no email address in the posting (apply yourself, then press Mark applied)') + '\n\n' +
  'Needs from you:\n' + bullets(d.missing_info) +
  (leftover.length ? '\n\nWARNING: the draft still contains ' + leftover.join(' ') + '. Edit it in the sheet before sending.' : '') +
  '\n\n--- DRAFT ---\nSubject: ' + subject + '\n\n' + body.slice(0, 2200) + '\n\nID: ' + ctx.id;
if (tg.length > 3900) tg = tg.slice(0, 3900) + '...';
return [{ json: { failed: !core, id: ctx.id, chatId: ctx.chatId, subject, body, tgText: tg } }];

