const fa = $('Find Application').first().json;
const row = fa.row || {};
const prof = {};
$('Read Profile 3').all().forEach(i => { if (i.json.Key) prof[i.json.Key] = i.json.Value; });
let job = {};
try { job = JSON.parse(row.JobJson || '{}'); } catch (e) { job = {}; }
const signature = prof.Signature ||
  ['Best regards,', prof.FullName, prof.Phone, prof.Email].filter(Boolean).join('\n');
return [{ json: {
  id: fa.id, chatId: fa.chatId, title: row.Title || job.title || '', company: row.Company || job.company || '',
  toEmail: row.ToEmail || '', subjectRequired: job.subject_required || '',
  jobJson: row.JobJson || '{}', jobExcerpt: String(row.JobText || '').slice(0, 5000),
  resumeText: prof.ResumeText || '', rules: prof.Rules || '',
  fullName: String(prof.FullName || '').trim(),
  expectedSalary: String(prof.ExpectedSalary || '').trim(), noticePeriod: String(prof.NoticePeriod || '').trim(),
  signature
}}];

const prof = {};
$('Read Profile 2').all().forEach(i => { if (i.json.Key) prof[i.json.Key] = i.json.Value; });
return [{ json: { fileId: String(prof.ResumeFileId || '').trim() } }];

const p = $('Parse Button').first().json;
const rows = $('Read Applications 2').all().map(i => i.json);
const row = rows.find(r => String(r.ID) === p.id);
return [{ json: Object.assign({}, p, { found: !!row, row: row || {} }) }];

const d = $('Normalize Input').first().json;
const parts = String(d.callbackData).split(':');
return [{ json: { action: parts[0], id: parts[1] || '', chatId: d.chatId, callbackId: d.callbackId, messageId: d.messageId } }];

const ctx = $('Build Context').first().json;
const raw = String($input.first().json.text || '').replace(/```json|```/g, '').trim();
let d = {};
try { d = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { d = {}; }
const list = a => Array.isArray(a) ? a.filter(Boolean).map(String) : [];
const bullets = a => list(a).map(x => '- ' + x).join('\n') || '- none';
const failed = d.score === undefined;
const score = Number(d.score || 0);
const low = score < ctx.minScore ? ' (below your minimum of ' + ctx.minScore + ')' : '';
const to = ctx.apply_method === 'email' ? (ctx.apply_email || '') : '';
let tg = 'Job: ' + ctx.title + ' at ' + ctx.company + '\n' +
  'Location: ' + (ctx.location || 'n/a') + ' | ' + (ctx.work_type || '') + '\n' +
  'Fit: ' + score + '/100, ' + (d.verdict || '?') + ', \n' + 'Role match: ' + (d.role_match || '?') + low + '\n' +
  'Scam risk: ' + (d.scam_risk || '?') + '\n' +
  'Apply by: ' + ctx.apply_method + (to ? ' to ' + to : '') + (ctx.deadline ? ' | deadline ' + ctx.deadline : '') + '\n\n' +
  'Why:\n' + bullets(d.reasons) + '\n\nGaps:\n' + bullets(d.gaps) + '\n\nFlags:\n' + bullets(d.scam_flags) +
  '\n\nSummary: ' + (ctx.summary || '') +
  '\n\nDo you want to apply for this job? Yes writes the application draft. Nothing is sent yet.\n\nID: ' + ctx.id;
if (tg.length > 3900) tg = tg.slice(0, 3900) + '...';
return [{ json: {
  failed, chatId: ctx.chatId, id: ctx.id, key: ctx.key, tgText: tg,
  date: new Date().toISOString().slice(0, 10),
  title: ctx.title, company: ctx.company, location: ctx.location || '',
  link: ctx.url || ctx.apply_url || '', method: ctx.apply_method, toEmail: to,
  score, verdict: d.verdict || '', scamRisk: d.scam_risk || '',
  jobJson: ctx.jobJson, jobText: ctx.jobExcerpt
}}];

const job = $('Parse Job').first().json;
const apps = $('Read Applications').all().map(i => i.json).filter(r => r.ID);
const prof = {};
$('Read Profile').all().forEach(i => { if (i.json.Key) prof[i.json.Key] = i.json.Value; });
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const key = norm(job.company) + '|' + norm(job.title);
const dup = apps.find(r => r.JobKey === key || (job.url && r.Link === job.url));
const signature = prof.Signature ||
  ['Best regards,', prof.FullName, prof.Phone, prof.Email].filter(Boolean).join('\n');
const slim = Object.assign({}, job); delete slim.jobText; delete slim.chatId;
return [{ json: Object.assign({}, job, {
  key, id: Math.random().toString(36).slice(2, 10),
  duplicate: !!dup, existingStatus: dup ? dup.Status : '',
  resumeText: prof.ResumeText || '', rules: prof.Rules || '',
  minScore: Number(prof.MinScore || 60), signature,
  fullName: String(prof.FullName || '').trim(),
  expectedSalary: String(prof.ExpectedSalary || '').trim(),
  noticePeriod: String(prof.NoticePeriod || '').trim(),
  jobJson: JSON.stringify(slim), jobExcerpt: String(job.jobText || '').slice(0, 5000)
})}];

const raw = String($input.first().json.text || '').replace(/```json|```/g, '').trim();
let job = {};
try { job = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); }
catch (e) { job = { parse_error: true }; }
const c = $('Clean Text').first().json;
job.chatId = c.chatId; job.url = c.url; job.jobText = c.jobText;
return [{ json: job }];

const base = $('Get URL or Text').first().json;
const j = $input.first().json;
let t = '';
if (base.hasUrl && typeof j.data === 'string') {
  t = j.data
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ').trim();
}
const pasted = base.hasUrl ? base.text.replace(base.url, '').trim() : base.text;
if (t.length < 300) t = (pasted + ' ' + t).trim();
return [{ json: { chatId: base.chatId, url: base.url, jobText: t.slice(0, 12000), short: t.length < 200 } }];

const d = $('Normalize Input').first().json;
const m = d.text.match(/https?:\/\/[^\s<>"')]+/i);
return [{ json: { chatId: d.chatId, text: d.text, url: m ? m[0] : '', hasUrl: !!m } }];

// EDIT THIS LINE: put your own Telegram user ID (from @userinfobot) between the quotes.
const ALLOWED = ['YOUR_TELEGRAM_USER_ID'];
const u = $input.first().json;
const cb = u.callback_query;
const msg = u.message || {};
const from = cb ? cb.from : msg.from;
const chatId = cb ? cb.message.chat.id : (msg.chat && msg.chat.id);
const text = (msg.text || msg.caption || '').trim();
let kind = 'job';
if (cb) kind = 'callback';
else if (/^\/(start|help)/i.test(text)) kind = 'help';
else if (!text) kind = 'empty';
return [{ json: {
  allowed: !!from && ALLOWED.includes(String(from.id)),
  kind, chatId, userId: from ? from.id : null, text,
  callbackData: cb ? cb.data : '', callbackId: cb ? cb.id : '',
  messageId: cb ? cb.message.message_id : msg.message_id
}}];
